-- Luxyra — 2026-10-28 — Bot : bons cadeaux vendus en ligne décrits EXACTEMENT comme l'application 6.8.4.
-- Problème : à « comment vendre des bons en ligne ? », le bot inventait des réglages (montants, durée…).
-- Vérifié dans le code : app.html (interrupteur « 🎁 Bons cadeaux en ligne », Paramètres › Site en ligne verrouillé hors Pro, grisé
-- sans Stripe actif ; bandeau de la tuile Bons cadeaux ; « ✏ Modifier » › Expiration ; « Ce bon cadeau a expiré »), bons-cadeaux.html
-- (montants 20/50/75/100 ou libre 10–2000 €, champs, 12 mois, scope tout, « Non remboursable »), site.html (lien « 🎁 Bon cadeau » si
-- bons_cadeaux_online_actif), edge function gc-create-checkout v7 déployée (10–2000 €, expiration +1 an, scope « tout », refus si
-- interrupteur éteint / Stripe non actif), recettes_en_ligne.sql (ticket « Bon cadeau BC-… (vente en ligne) » au paiement ;
-- remboursement d'un bon : uniquement via charge.refunded Stripe, pas encore coché ; aucun bouton de remboursement dans l'app).
-- Idempotent (INSERT … ON CONFLICT (cle) DO UPDATE, contenus complets). Aucun réglage d'établissement modifié.
BEGIN;
INSERT INTO public.support_bot_kb (cle,titre,ordre,contenu,actif,maj_le) VALUES ('bons',$kb$Bons cadeaux$kb$,12,$kb$Accueil → « Bons cadeaux » : onglets Actifs, Utilisés, Expirés, Tous ; « 🎁 Offrir un bon » (gratuit), recherche, « Export CSV ». Sur un bon : Imprimer, Modifier, Annuler.
Vendre un bon : Encaissement → « 🎁 Bon cadeau » → « Créer un bon cadeau » (encaissé avec le ticket). Utiliser un bon : mode de paiement « Bon cadeau ».
Depuis le 14/10/2026 : le bon choisi est seulement RÉSERVÉ sur le panier (solde réel relu) puis DÉBITÉ au moment où le ticket est validé (un panier abandonné ne consomme plus le bon). Échec : « Bon cadeau CODE non débité : … Aucun ticket n'a été créé ; choisissez un autre règlement. » Un bon absent de l'appareil est cherché dans la base. Bon acheté en ligne dont le paiement n'est pas confirmé : refusé (« Paiement en ligne de ce bon non confirmé : il ne peut pas encore être utilisé. ») ; bon annulé : « Ce bon a été annulé. » ; réseau : « Vérification du bon impossible (connexion). Réessayez. » Un bon ne s'applique qu'une fois par ticket. Ticket annulé = bon recrédité automatiquement.
Vente en ligne (sur le site de l'établissement) : possible seulement si l'établissement l'a activée, interrupteur « 🎁 Bons cadeaux en ligne » dans Paramètres › « Site en ligne » (forfait Pro, compte Stripe actif). Montants, durée de validité (12 mois) et usage (tout) n'y sont pas réglables par l'établissement. Achat, caisse, remboursement : voir l'entrée « Bons cadeaux vendus en ligne ». Le client retrouve ses bons dans son espace client, onglet « 🎁 Bons cadeaux ».$kb$,true,now())
  ON CONFLICT (cle) DO UPDATE SET titre=EXCLUDED.titre, ordre=EXCLUDED.ordre, contenu=EXCLUDED.contenu, actif=true, maj_le=now();
INSERT INTO public.support_bot_kb (cle,titre,ordre,contenu,actif,maj_le) VALUES ('bons_cadeaux_1016',$kb$Bons cadeaux : vendre, offrir, modifier, imprimer, utiliser$kb$,1340,$kb$Vendre : dans la caisse, « 🎁 Bon cadeau » › « 🎁 Créer un bon cadeau » : « Montant TTC » (montants proposés ou « Autre montant »), « Acheteur », « Bénéficiaire », « Message », « Validité » (6, 12, 18 ou 24 mois), « Utilisable sur » (Tout, Prestations, Produits), « Code du bon » (ou « Auto ») › « Créer le bon ». Le bon est ajouté au ticket et encaissé avec.
Offrir (gratuit : jeu concours, geste commercial) : tuile « Bons cadeaux » › « 🎁 Offrir un bon » (permission « Appliquer une remise ») : « Montant du bon », « Bénéficiaire / motif », « Code du bon », « Validité » (6 ou 12 mois), « Utilisable sur » › « 🎁 Créer le bon offert ». Non facturé, tracé en comptabilité.
Suivre : Accueil › « Bons cadeaux » : onglets « Tous », « Actifs », « Utilisés », « Expirés », totaux, « 📄 Export CSV », « 🔍 Rechercher un bon cadeau ». Sur un bon : « 🖨 Imprimer », « ✏ Modifier » (acheteur, bénéficiaire, message, expiration, utilisable sur), « ✖ Annuler ».
Utiliser : au paiement, tuile « Bon cadeau » ; le bon est débité à la validation du ticket. Le reste éventuel reste sur le bon. Un bon « Prestations » ne paie que les prestations (un bon « Produits », que les produits). TVA du bon (comptée à la vente ou à l'utilisation) : voir l'entrée « Bons cadeaux : TVA comptée à la vente ou à l'utilisation ».
Validité : bon vendu en caisse 6, 12, 18 ou 24 mois (choisi à la création) ; bon offert 6 ou 12 mois ; bon acheté en ligne 12 mois à partir de l'achat (durée non réglable par l'établissement). Pour tous les bons, la date se change ensuite par « ✏ Modifier » › « Expiration ». Bon expiré présenté en caisse : « Ce bon cadeau a expiré ».
Vente en ligne : seulement si l'établissement l'a activée (interrupteur « 🎁 Bons cadeaux en ligne », Paramètres › « Site en ligne ») ; voir l'entrée « Bons cadeaux vendus en ligne ».$kb$,true,now())
  ON CONFLICT (cle) DO UPDATE SET titre=EXCLUDED.titre, ordre=EXCLUDED.ordre, contenu=EXCLUDED.contenu, actif=true, maj_le=now();
INSERT INTO public.support_bot_kb (cle,titre,ordre,contenu,actif,maj_le) VALUES ('bons_cadeaux_en_ligne_1028',$kb$Bons cadeaux vendus en ligne (site de l'établissement) : réglage, achat, caisse, utilisation, remboursement$kb$,1343,$kb$Disponibilité : la vente de bons cadeaux en ligne dépend du réglage de CHAQUE établissement (désactivée tant qu'il ne l'a pas activée). L'état de cet interrupteur n'est PAS dans le contexte : ne jamais affirmer qu'elle est activée, disponible ou indisponible pour l'établissement ; dire qu'elle dépend de son réglage et indiquer où le vérifier.
Le seul réglage : Paramètres › « Site en ligne » (forfait Pro) › carte « Activation » › interrupteur « 🎁 Bons cadeaux en ligne ». Il est grisé, avec « (Stripe Connect requis) », tant que le compte Stripe n'est pas actif (Paramètres › « Paiements en ligne »). À l'activation : « ✅ Vente en ligne activée. Vos clients peuvent maintenant acheter des bons cadeaux depuis votre site. » Le même interrupteur la désactive.
Rien d'autre n'est réglable pour la vente en ligne : l'établissement ne choisit PAS les montants, la validité, « Utilisable sur », ni un minimum ou un maximum. Valeurs fixes : montants proposés 20, 50, 75 ou 100 €, ou montant libre de 10 € à 2 000 € ; validité 12 mois à partir de l'achat (durée non réglable ; la date d'un bon peut ensuite être changée bon par bon, voir Utilisation) ; utilisable sur tout (prestations et produits), en une ou plusieurs fois.
Lien de la page de vente : tuile « Bons cadeaux » : vente activée, bandeau « Vente en ligne activée » avec l'adresse (luxyra.fr/votre-adresse/bons-cadeaux), « 📋 Copier », « ↗ Ouvrir » ; vente désactivée, bouton « ⚙️ Activer dans Paramètres ». Sur le site de l'établissement, le lien « 🎁 Bon cadeau » n'apparaît que si la vente est activée ; sinon la page indique « Ce salon ne propose pas actuellement de bons cadeaux en ligne. Contactez le salon directement pour offrir un bon cadeau. »
Achat par le client, sur la page de vente : montant, « Offert par » (obligatoire), « Offert à » (facultatif), « Message » (obligatoire, 280 caractères au plus), choix d'un style, « Votre email » (obligatoire) et « Téléphone » (facultatif), puis « Payer … € par carte » : paiement par carte sur Stripe ; l'argent va sur le compte Stripe de l'établissement. Ensuite, page de confirmation avec le code du bon (BC-…), et e-mail à l'acheteur. Un client connecté retrouve ses bons dans son espace client, onglet « 🎁 Bons cadeaux ».
En caisse, rien à saisir : dès que le paiement est confirmé, Luxyra crée automatiquement le ticket de caisse scellé « Bon cadeau BC-… (vente en ligne) », réglé « En ligne (Stripe) », compté dans la clôture du jour (ligne « Payés en ligne ») ; le bon apparaît dans la tuile « Bons cadeaux ». TVA : même règle qu'un bon vendu en caisse, appliquée automatiquement selon les taux de l'établissement (un bon en ligne est utilisable sur tout) : même taux pour les prestations et les produits = bon à usage unique (TVA comptée à la vente) ; taux différents = bon à usage multiple (hors chiffre d'affaires, TVA à l'utilisation). Voir l'entrée « Bons cadeaux : TVA comptée à la vente ou à l'utilisation ».
Utilisation : comme un bon vendu en caisse (au paiement, tuile « Bon cadeau » ; débité à la validation du ticket ; le reste éventuel reste sur le bon). Paiement en ligne pas encore confirmé : « Paiement en ligne de ce bon non confirmé : il ne peut pas encore être utilisé. » Bon expiré : « Ce bon cadeau a expiré » ; la date peut être changée : tuile « Bons cadeaux » › le bon › « ✏ Modifier » › « Expiration ».
Remboursement d'un bon acheté en ligne : la page de vente et le bon indiquent « Non remboursable ». Luxyra n'a AUCUN bouton pour rembourser sur la carte du client un bon acheté en ligne, et un remboursement fait directement dans le tableau de bord Stripe n'est PAS encore enregistré automatiquement dans la caisse (la caisse et l'argent ne correspondraient plus). Donc : ne jamais conseiller de rembourser sur Stripe, ni de faire un avoir ou d'annuler le ticket de vente. Client qui demande le remboursement d'un bon acheté en ligne, ou bon déjà remboursé sur Stripe : transmettre à un humain <ESCALATE/>.
Paiement refusé ou page en erreur alors que la vente est activée : <ESCALATE/>.$kb$,true,now())
  ON CONFLICT (cle) DO UPDATE SET titre=EXCLUDED.titre, ordre=EXCLUDED.ordre, contenu=EXCLUDED.contenu, actif=true, maj_le=now();
INSERT INTO public.support_bot_kb (cle,titre,ordre,contenu,actif,maj_le) VALUES ('bons_cadeaux_tva_1028',$kb$Bons cadeaux : TVA comptée à la vente ou à l'utilisation$kb$,1341,$kb$Règle (loi : article 256 ter du code général des impôts), appliquée automatiquement par Luxyra à la CRÉATION du bon, selon les taux de TVA de l'établissement et le choix « Utilisable sur » (Tout, Prestations, Produits). Un encadré l'explique sous « Utilisable sur » avant de créer le bon.
Bon à usage unique : tous les articles que le bon peut payer ont le même taux de TVA (ex. tout à 20 %, ou bon limité aux prestations). La TVA est comptée à la vente ; le bon entre dans le chiffre d'affaires du jour de la vente. Quand il sert, il est déduit (« BON CADEAU … (DÉJÀ ENCAISSÉ À LA VENTE) ») et n'est pas compté une deuxième fois. Il ne peut pas payer un article soumis à un autre taux (message « Ce bon (TVA … comptée à sa vente) ne peut pas régler des articles soumis à un autre taux de TVA. »).
Bon à usage multiple : le bon peut payer des articles à des taux différents (ex. prestations 20 % et produits 5,5 %, bon « Tout »). Sa vente n'est PAS du chiffre d'affaires et ne contient pas de TVA (ticket : « Bon à usage multiple – TVA exigible à l'utilisation », ligne « Non soumis »). Le jour où il sert, c'est un moyen de paiement (« Payé en Bon cadeau … (bon à usage multiple) ») : le chiffre d'affaires et la TVA sont comptés sur les articles réellement achetés. Pas de remise possible sur un ticket qui contient la vente d'un tel bon.
Bon limité aux prestations (ou aux produits) : il ne paie QUE ces articles ; le reste du ticket se règle normalement.
Solde d'un bon à usage multiple jamais utilisé : à l'expiration, aucune TVA ; il apparaît dans les documents comptables du mois (soldes expirés).
Établissement en franchise de TVA : pas de TVA ; le bon compte dans les recettes le jour de la vente. Micro-entreprise : le bon compte dans les recettes encaissées le jour de sa vente ; ce qu'il paie ensuite n'est pas une nouvelle recette (livre des recettes, déclaration URSSAF).
Bons vendus avant la mise en service de cette règle (28/10/2026) : ils gardent leur traitement d'origine (comptés à la vente) jusqu'à épuisement ; seule nouveauté, un bon « Prestations » n'est plus réparti sur les produits du ticket. Les tickets déjà enregistrés ne sont jamais modifiés.
Où voir : tuile « Bons cadeaux » (chaque bon indique « Usage unique : CA et TVA (…) à la vente » ou « Usage multiple : hors CA, TVA à l'utilisation ») ; Caisse › « Journal / Bande Z » › « Documents comptables » › « Bons cadeaux à usage multiple (CSV) » (ventes, utilisations, soldes expirés, bons en circulation) ; onglet « 9 — Bons usage multiple » de l'Excel ; section 6 du rapport ; clôture Z et bande Z : ligne « Bons à usage multiple vendus (hors chiffre d'affaires) ». Comptes : Paramètres › Conformité caisse › « Comptes comptables pour l'export » › « Bons à usage multiple (dette) » (4191 par défaut) et « Bons expirés (produit hors TVA) » (758 par défaut), à valider avec le comptable.
Annuler la vente d'un bon vendu en caisse : annuler le ticket de vente (Caisse › « Gestion des tickets » › le ticket › « Annuler ») ; le bon est désactivé s'il n'a jamais servi ; s'il a déjà servi, régularisation à faire à la main (message affiché). Bon acheté en ligne : ne pas annuler son ticket soi-même, voir l'entrée « Bons cadeaux vendus en ligne » (remboursement).
Le client conteste le traitement fiscal ou l'expert-comptable demande un autre traitement : Luxyra n'a pas de réglage pour changer la règle ; transmettre à un humain <ESCALATE/>.$kb$,true,now())
  ON CONFLICT (cle) DO UPDATE SET titre=EXCLUDED.titre, ordre=EXCLUDED.ordre, contenu=EXCLUDED.contenu, actif=true, maj_le=now();
INSERT INTO public.support_bot_kb (cle,titre,ordre,contenu,actif,maj_le) VALUES ('recettes_en_ligne_1028',$kb$Paiements en ligne : enregistrés automatiquement dans la caisse$kb$,1342,$kb$Depuis le 28/10/2026 (Luxyra 6.8.4), CHAQUE paiement fait en ligne par un client est enregistré automatiquement dans la caisse de l'établissement, au moment où le paiement est confirmé, même si l'application est fermée sur tous les appareils : ticket de caisse sécurisé, réglé « En ligne (Stripe) », compté dans la clôture du jour (ligne « Payés en ligne ») et dans tous les documents comptables. Rien à saisir.
Concerné : acompte de rendez-vous (ticket « Acompte en ligne »), empreinte bancaire capturée (ticket « Empreinte encaissée », pour le montant RÉELLEMENT débité, même si une partie seulement est capturée), bon cadeau acheté en ligne, seulement si l'établissement a activé la vente en ligne de bons (ticket « Bon cadeau BC-… (vente en ligne) », même règle de TVA qu'un bon vendu en caisse ; le n° du ticket est dans l'e-mail de l'acheteur), carte d'abonnement payée en ligne, commande Click & Collect payée en ligne.
Remboursements faits DEPUIS LUXYRA (acompte remboursé, commande annulée et remboursée) : ils créent automatiquement un ticket négatif qui renvoie au ticket du paiement : acompte en ligne, acompte conservé, empreinte encaissée, carte d'abonnement (désactivée si remboursée en totalité), commande Click & Collect. Un bon cadeau acheté en ligne ne se rembourse pas depuis Luxyra (aucun bouton) : voir l'entrée « Bons cadeaux vendus en ligne ». Le total remboursé ne dépasse jamais le montant encaissé. Rien à faire dans Luxyra. Remboursement fait directement dans le tableau de bord Stripe (hors Luxyra) : il n'est PAS encore enregistré automatiquement dans la caisse ; conseiller de faire les remboursements depuis Luxyra (sauf bon cadeau acheté en ligne : <ESCALATE/>) ; si un remboursement a déjà été fait sur Stripe, ne rien saisir soi-même et transmettre à un humain <ESCALATE/>. Paiement fait avant le 28/10/2026, sans ticket serveur : le remboursement s'enregistre par un avoir en caisse (<ESCALATE/> si l'établissement le demande).
Numéros : les tickets créés par le serveur ont leur propre série (900001, 900002…), distincte des appareils : jamais deux tickets au même numéro. Le n° légal (serveur) reste continu. La Z indique « Tickets » et « Paiements en ligne ».
Message « Mettez l'application à jour » (ou ticket refusé « LX_APP_OBSOLETE ») : finir l'encaissement, fermer complètement l'application puis la rouvrir (ou recharger la page) ; les tickets en attente partent seuls après la mise à jour, aucune vente perdue.
Clôture automatique de la nuit non faite / journée restée ouverte : un rendez-vous encaissé de cette journée n'a pas son ticket au serveur (appareil hors connexion ou pas à jour). Ouvrir l'application sur l'appareil concerné, connexion active, puis recharger : le ticket part et la journée se clôture. Ticket arrivé alors que sa journée était déjà clôturée : il est enregistré dans la journée en cours avec la mention « Vente du … enregistrée le … » (date réelle conservée) ; c'est normal, rien n'est perdu ni compté deux fois. « Forcer la clôture » : les tickets refusés restent en attente sur l'appareil et partent dès que possible. Si un ticket reste en attente plus d'un jour : <ESCALATE/>.
Clôture refusée « Clôture du … impossible : vente(s) non transmise(s) » (6.8.4) : des ventes encaissées ce jour-là (n° de ticket listés) ont été faites sur un AUTRE appareil dont les tickets ne sont pas arrivés. Allumer les autres appareils, connexion active, recharger l'application (version 6.8.4 ou plus), puis « Réessayer ». En dernier recours (appareil perdu ou hors service) : « Forcer la clôture (administrateur) » : code PIN administrateur + motif, possible 5 minutes après le premier contrôle (l'heure s'affiche si c'est trop tôt) ; le forçage est tracé (journal NF525) avec la liste des ventes ; si elles arrivent plus tard, elles sont enregistrées dans la journée en cours avec leur date réelle. Message « Journée du … non clôturée » : les clôtures se font dans l'ordre des dates ; la journée précédente doit être clôturée d'abord (transmettre ses tickets ou forcer sa clôture) ; la clôture de nuit fera ensuite les journées dans l'ordre ; on peut continuer à encaisser. La clôture du mois / de l'année / de l'exercice attend aussi qu'aucune journée ne reste ouverte et se refait chaque nuit. Carte rouge « Caisse : action requise » sur l'accueil : elle dit quoi faire ; si elle reste plus de deux jours : <ESCALATE/>. « Journée du … non clôturée depuis plus de 60 jours » : le forçage depuis l'application n'est plus possible ; déblocage par l'administrateur Luxyra (forçage tracé au journal NF525) : <ESCALATE/>. L'historique repris d'un ancien logiciel (rendez-vous importés) ne bloque jamais les clôtures.
Ventes reportées dans les documents comptables (rapport « 5 ter », Excel onglet « 10 — Ventes reportées », ZIP, e-mail au comptable, FEC) : vente enregistrée un jour postérieur à sa date réelle (journée déjà clôturée) ; comptée le jour d'enregistrement comme la caisse, signalée avec la date réelle et la période de TVA d'origine pour que le comptable régularise la TVA si le mois change. C'est normal.
Carte d'abonnement achetée sur le site : le tarif, les remises et la durée sont ceux réglés dans l'application (Paramètres), jamais ceux de la page ; une carte qui n'est plus proposée ne peut pas être payée.
Click & Collect payé en ligne : la commande est DÉJÀ en caisse depuis le paiement. Au retrait, le bouton « Remettre (déjà en caisse : ticket n° …) » marque la commande remise et sort les produits du stock, SANS nouveau ticket : ne pas l'encaisser une 2e fois. Une commande « À régler au salon » s'encaisse toujours avec « Encaisser puis remettre ».
Paiement reçu après la clôture Z du soir : il est enregistré automatiquement dans la journée suivante (la date du paiement reste indiquée sur le ticket). Un message peut dire « le serveur l'enregistre automatiquement » : attendre quelques minutes. S'il manque encore le lendemain : <ESCALATE/>.
Bon cadeau acheté en ligne utilisé en caisse : déduit (bon à usage unique) ou pris comme moyen de paiement (bon à usage multiple), jamais compté deux fois.
Caisse en mode test (essai) : ces tickets sont des tickets de TEST, effacés au passage en caisse réelle comme les autres.$kb$,true,now())
  ON CONFLICT (cle) DO UPDATE SET titre=EXCLUDED.titre, ordre=EXCLUDED.ordre, contenu=EXCLUDED.contenu, actif=true, maj_le=now();
COMMIT;
-- Contrôle : select cle, md5(contenu), length(contenu) from public.support_bot_kb where cle in ('bons','bons_cadeaux_1016','bons_cadeaux_en_ligne_1028','bons_cadeaux_tva_1028','recettes_en_ligne_1028');
